and (
exists ( select 1 from t_user global_admin inner join t_user_role_map global_admin_role_map on global_admin_role_map.user_id = global_admin.user_id inner join t_role global_admin_role on global_admin_role.role_id = global_admin_role_map.role_id where global_admin.user_id = #{viewerUserId} and coalesce(global_admin.status, 0) = 0 and upper(global_admin_role.name) in ('ADMIN', 'SUPER_ADMIN', 'SUPERADMIN') )
copywriting.user_id = #{viewerUserId}
or exists ( select 1 from t_copywriting_expert_assignment expert_assignment inner join t_user expert_user on expert_user.user_id = expert_assignment.expert_user_id and coalesce(expert_user.status, 0) = 0 where expert_assignment.account_user_id = copywriting.user_id and expert_assignment.expert_user_id = #{viewerUserId} and exists ( select 1 from t_user_role_map expert_role_map inner join t_role expert_role on expert_role.role_id = expert_role_map.role_id where expert_role_map.user_id = #{viewerUserId} and upper(expert_role.name) = 'EXPERT' ) )
or exists ( select 1 from t_copywriting_organization_admin_assignment organization_assignment inner join t_user organization_user on organization_user.user_id = organization_assignment.admin_user_id and coalesce(organization_user.status, 0) = 0 where organization_assignment.account_user_id = copywriting.user_id and organization_assignment.admin_user_id = #{viewerUserId} and exists ( select 1 from t_user_role_map organization_role_map inner join t_role organization_role on organization_role.role_id = organization_role_map.role_id where organization_role_map.user_id = #{viewerUserId} and upper(organization_role.name) = 'ORG_ADMIN' ) )
)

where 1 = 1


